create or replace view gov_repo.v_ai_act_high_risk_dashboard as select s.organisation_id,s.system_id,s.system_code,s.name as system_name,s.version,s.lifecycle,s.risk_class,s.annex_iii_sector,s.gpai_tier,s.organisation_role,s.ce_marking_status,s.ce_marking_date,s.ce_marking_notified_body,s.ce_marking_nb_certificate_ref,s.doc_ref,s.doc_issued_date,s.eu_ai_db_registered,s.eu_ai_db_ref,s.eu_ai_db_system_uuid,s.eu_ai_db_submission_date,s.conformity_assessment_id,s.conformity_procedure,s.conformity_version,s.conformity_valid_until,(s.conformity_valid_until is not null and s.conformity_valid_until<current_date) as conformity_expired,(s.conformity_valid_until is not null and s.conformity_valid_until<current_date+interval '90 days' and s.conformity_valid_until>=current_date) as conformity_expiring_soon,s.cg_sys_004_tech_doc,s.technical_doc_last_updated,s.cg_sys_005_risk_mgmt,s.residual_risk_level,s.risk_mgmt_next_review,(s.risk_mgmt_next_review is not null and s.risk_mgmt_next_review<current_date) as risk_review_overdue,s.cg_sys_006_human_oversight,u_oversight.full_name as oversight_person_name,s.pms_plan_documented,s.pms_next_review,(s.pms_next_review is not null and s.pms_next_review<current_date) as pms_overdue,s.serious_incidents_reported,s.annex_iii_exception_claimed,s.fria_conducted,s.fria_date,s.iso_42001_certified,s.iso_42001_cert_expires,(s.iso_42001_cert_expires is not null and s.iso_42001_cert_expires<current_date) as iso42001_cert_expired,not s.cg_sys_004_tech_doc as gap_tech_doc,not s.cg_sys_005_risk_mgmt as gap_risk_mgmt,not s.cg_sys_006_human_oversight as gap_oversight,not s.cg_sys_007_conformity as gap_conformity,not s.cg_sys_008_post_market as gap_pms,(s.eu_ai_db_registered=false and s.lifecycle in ('production','conformity_assessed')) as gap_eu_db,u_owner.full_name as owner_name,u_owner.email as owner_email from gov_repo.ai_systems s left join gov_repo.governance_users u_owner on u_owner.user_id=s.owner_user_id left join gov_repo.governance_users u_oversight on u_oversight.user_id=s.oversight_person_id where s.risk_class='high' and s.status!='decommissioned' order by case s.lifecycle when 'production' then 1 when 'conformity_assessed' then 2 when 'pre_market_review' then 3 when 'testing' then 4 else 5 end,s.name;
create or replace view gov_repo.v_ai_system_conformity_status as select s.organisation_id,s.system_id,s.system_code,s.name as system_name,s.risk_class,s.lifecycle,s.version,s.ce_marking_status,s.conformity_procedure,ca.assessment_code,ca.assessment_type,ca.status as assessment_status,ca.outcome,ca.start_date as assessment_start,ca.completion_date as assessment_completed,ca.valid_until as assessment_valid_until,ca.assessor_org,ca.non_conformities,s.technical_doc_evidence_id,e_techdoc.evidence_code as tech_doc_evidence_code,e_techdoc.status as tech_doc_evidence_status,e_techdoc.verified_at as tech_doc_verified_at,s.declaration_of_conformity_id,e_doc.evidence_code as doc_evidence_code,e_doc.status as doc_evidence_status,s.pms_plan_evidence_id,e_pms.evidence_code as pms_evidence_code,e_pms.status as pms_evidence_status,s.doc_ref,s.doc_issued_date,s.doc_issued_by,s.eu_ai_db_registered,s.eu_ai_db_ref,s.eu_ai_db_system_uuid,s.iso_42001_certified,s.iso_42001_cert_ref,s.iso_42001_cert_expires,(ca.assessment_id is not null and ca.outcome='conformant' and s.ce_marking_status='marked' and s.doc_ref is not null and s.eu_ai_db_registered=true) as fully_conformant from gov_repo.ai_systems s left join gov_repo.conformity_assessments ca on ca.assessment_id=s.conformity_assessment_id left join gov_repo.evidence e_techdoc on e_techdoc.evidence_id=s.technical_doc_evidence_id left join gov_repo.evidence e_doc on e_doc.evidence_id=s.declaration_of_conformity_id left join gov_repo.evidence e_pms on e_pms.evidence_id=s.pms_plan_evidence_id where s.status!='decommissioned';
create or replace view gov_repo.v_ai_system_agent_roster as select s.organisation_id,s.system_id,s.system_code,s.name as system_name,s.risk_class as system_risk_class,s.lifecycle as system_lifecycle,a.agent_id,a.agent_code,a.name as agent_name,a.agent_type,a.risk_level as agent_risk_level,a.ai_act_risk_class as agent_ai_act_class,a.oversight_level,a.status as agent_status,a.deployment_env,a.model_name,a.model_provider,a.model_is_local,a.cg_ag_001_registered,a.cg_ag_002_owner,a.cg_ag_003_model_reg,a.cg_ag_007_oversight,a.cg_ag_010_classified,a.cg_ag_012_autonomous_governed,not a.cg_ag_001_registered as gap_001,not a.cg_ag_002_owner as gap_002,not a.cg_ag_003_model_reg as gap_003,not a.cg_ag_007_oversight as gap_007,not a.cg_ag_010_classified as gap_010,(a.agent_type='autonomous' and not a.cg_ag_012_autonomous_governed) as gap_012,u.full_name as agent_owner_name,u.email as agent_owner_email from gov_repo.ai_systems s join gov_repo.agents a on a.ai_system_id=s.system_id join gov_repo.governance_users u on u.user_id=a.owner_user_id where a.status not in ('decommissioned') and s.status!='decommissioned' order by s.system_code,case a.risk_level when 'critical' then 1 when 'high' then 2 when 'medium' then 3 else 4 end,a.agent_code;;
